using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using Assets.Script.DynamicCards;using Cynthia.Card;
public static class MotionWork {public static void Run(){new GameObject("Motion switching regression").AddComponent<MotionSwitchRegression>();}}
public class MotionSwitchRegression:MonoBehaviour {
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionRepair-20260910/SwitchRegression/";
object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
Color32[] Save(DynamicCardView v,string name){var rt=(RenderTexture)F(v,"texture");var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;File.WriteAllBytes(W+name+".png",t.EncodeToPNG());var result=t.GetPixels32();Destroy(t);return result;}
IEnumerator Start(){Directory.CreateDirectory(W);var ed=Resources.FindObjectsOfTypeAll<EditorInfo>().First(x=>x.gameObject.scene.IsValid());var all=GwentMap.GetCards(isHasAgent:true).ToList();var cards=all.Where(x=>new[]{"22005","32015","70093","70159"}.Contains(x.CardId)).ToList();var log=new List<string>();for(int round=0;round<3;round++){ed.SetShowCardInfo(all.Take(24).ToList());ed.SelectSwitchUICard(all.First());yield return new WaitForSecondsRealtime(8);ed.SetShowCardInfo(cards);for(int i=0;i<16;i++){ed.SelectSwitchUICard(cards[i%cards.Count]);yield return new WaitForSecondsRealtime(.07f);}ed.SelectSwitchUICard(cards[round]);yield return new WaitForSecondsRealtime(7);var views=FindObjectsOfType<DynamicCardView>().Where(v=>F(v,"texture")!=null).ToArray();var nodes=views.Select(v=>((GameObject)F(v,"model")).GetComponentsInChildren<Transform>(true)).ToArray();var pose=nodes.Select(ns=>ns.Select(t=>t.localRotation).ToArray()).ToArray();var pics=views.Select((v,i)=>Save(v,round+"-"+F(v,"artId")+"-"+F(v,"preview")+"-a")).ToArray();yield return new WaitForSecondsRealtime(6);for(int i=0;i<views.Length;i++){var v=views[i];if(v==null||F(v,"texture")==null){log.Add(round+" view changed");continue;}var p=Save(v,round+"-"+F(v,"artId")+"-"+F(v,"preview")+"-b");long delta=0;for(int k=0;k<p.Length;k++)delta+=Math.Abs(p[k].r-pics[i][k].r)+Math.Abs(p[k].g-pics[i][k].g)+Math.Abs(p[k].b-pics[i][k].b);log.Add(round+" "+F(v,"artId")+" preview="+F(v,"preview")+" pixels="+delta+" moving="+nodes[i].Where((t,j)=>Quaternion.Angle(t.localRotation,pose[i][j])>.001f).Count());}File.WriteAllLines(W+"results.txt",log);}File.WriteAllText(W+"complete.txt","3 reloads, 48 rapid preview switches");Destroy(gameObject);}}
